using System.Text.Json;
using IProfiler.Core.Domain;
using IProfiler.Core.Recognition;
using IProfiler.Infrastructure.Barcodes;
using Microsoft.Extensions.Logging.Abstractions;

namespace IProfiler.Tests.Barcodes;

/// <summary>
/// Barcode / QR / patch-code reading on 300 dpi 1-bit CCITT G4 TIFFs, the default scanner output
/// (generated by tools/make-barcode-samples.py with zxing-cpp, a different implementation from the reader).
/// </summary>
public class BarcodeTests
{
    private static readonly string Data = Path.Combine(AppContext.BaseDirectory, "TestData");

    public static string BwPage => Path.Combine(Data, "barcode", "bw-g4-300dpi.tif");

    private readonly ZXingBarcodeProvider _barcodes = new(NullLogger<ZXingBarcodeProvider>.Instance);
    private readonly OpenCvPatchCodeDetector _patches = new(NullLogger<OpenCvPatchCodeDetector>.Instance);

    public static TheoryData<string> Symbologies => new(Expected.Select(e => e.Symbology));

    public static TheoryData<string, PatchCode> PatchSheets => new()
    {
        { "patch-1.tif", PatchCode.Patch1 },
        { "patch-2.tif", PatchCode.Patch2 },
        { "patch-3.tif", PatchCode.Patch3 },
        { "patch-4.tif", PatchCode.Patch4 },
        { "patch-6.tif", PatchCode.Patch6 },
        { "patch-T.tif", PatchCode.PatchT },
    };

    [Fact]
    public async Task Page_read_finds_code39_code128_and_qr_on_a_g4_tiff()
    {
        var results = await _barcodes.ReadPageAsync(BwPage);

        Assert.Equal(
            Expected.Select(e => (Enum.Parse<BarcodeSymbology>(e.Symbology), e.Text)).Order(),
            results.Select(r => (r.Symbology, r.Text)).Order());
        foreach (var e in Expected)
            AssertInside(results.Single(r => r.Text == e.Text).Box, e.Region);
    }

    [Theory]
    [MemberData(nameof(Symbologies))]
    public async Task Region_read_returns_only_the_barcode_in_the_drawn_region(string symbology)
    {
        var expected = Expected.Single(e => e.Symbology == symbology);

        var results = await _barcodes.ReadRegionAsync(BwPage, expected.Region);

        var result = Assert.Single(results);
        Assert.Equal(Enum.Parse<BarcodeSymbology>(symbology), result.Symbology);
        Assert.Equal(expected.Text, result.Text);
        AssertInside(result.Box, expected.Region);
    }

    [Fact]
    public async Task Region_without_a_barcode_is_empty()
    {
        // The address block: text only.
        var results = await _barcodes.ReadRegionAsync(BwPage, new PixelRect(180, 380, 1400, 220));

        Assert.Empty(results);
    }

    [Fact]
    public async Task Region_outside_the_page_is_empty()
    {
        Assert.Empty(await _barcodes.ReadRegionAsync(BwPage, new PixelRect(9000, 9000, 50, 50)));
    }

    [Theory]
    [MemberData(nameof(PatchSheets))]
    public async Task Patch_sheet_is_recognised(string file, PatchCode expected)
    {
        Assert.Equal(expected, await _patches.DetectAsync(Path.Combine(Data, "patch", file)));
    }

    [Fact]
    public async Task Page_with_1d_barcodes_is_not_a_patch_sheet()
    {
        Assert.Null(await _patches.DetectAsync(BwPage));
    }

    [Fact]
    public async Task Text_page_is_not_a_patch_sheet()
    {
        Assert.Null(await _patches.DetectAsync(Path.Combine(Data, "ocr", "invoice-150dpi.png")));
    }

    private sealed record ExpectedBarcode(string Symbology, string Text, PixelRect Region);

    private static IReadOnlyList<ExpectedBarcode> Expected
    {
        get
        {
            using var json = JsonDocument.Parse(File.ReadAllText(Path.Combine(Data, "barcode", "bw-g4-300dpi.json")));
            return json.RootElement.GetProperty("barcodes").EnumerateArray()
                .Select(b =>
                {
                    var r = b.GetProperty("region").EnumerateArray().Select(v => v.GetInt32()).ToArray();
                    return new ExpectedBarcode(b.GetProperty("symbology").GetString()!, b.GetProperty("text").GetString()!,
                        new PixelRect(r[0], r[1], r[2], r[3]));
                })
                .ToList();
        }
    }

    private static void AssertInside(PixelRect inner, PixelRect outer) =>
        Assert.True(inner.X >= outer.X && inner.Y >= outer.Y &&
                    inner.X + inner.Width <= outer.X + outer.Width &&
                    inner.Y + inner.Height <= outer.Y + outer.Height,
            $"{inner} is not inside {outer}");
}
